<?php
require __DIR__.'/../vendor/autoload.php';require __DIR__.'/../includes/report_input_templates.php';require __DIR__.'/../includes/biaya_workbook.php';require __DIR__.'/../includes/biaya_template_history.php';
function groupBiayaCheck($ok,$message){if(!$ok)throw new RuntimeException($message);}
foreach([2025,2026,2027] as $year){
 $book=buildReportInputTemplate('BIAYA',$year.'-10');$targetName=$year===2025?'TARGET ROLLING':'TARGET';$t=$book->getSheetByName($targetName);$a=$book->getSheetByName('REALISASI');groupBiayaCheck($book->getSheetNames()===[$targetName,'REALISASI','_TEMPLATE'],'Two visible sheets only');
 foreach([$t,$a] as $sheet)groupBiayaCheck(count(locateBiayaInputTables($sheet,true))===6,'Six GB tables per sheet');
 foreach(locateBiayaInputTables($t,true) as $gbIndex=>$table){$r=$table['first'];$gb=$table['gb'];$t->setCellValue('B'.$r,'EXIS');$t->setCellValue('C'.$r,1);$t->setCellValue('D'.$r,'Synthetic GB '.$gb);$t->setCellValue('E'.$r,$gb);$t->setCellValue('F'.$r,0);$a->setCellValue('E'.$r,-1);groupBiayaCheck($a->getCell('D'.$r)->getValue()==="='".$targetName."'!D".$r,'Actual identity references matching Target row');groupBiayaCheck($t->getCell('E'.$table['total'])->getValue()==='=SUM(E'.$table['first'].':E'.$table['last'].')','Simple GB subtotal');}
 $table=locateBiayaInputTables($t,true)[4];foreach([$t,$a] as $sheet)$sheet->insertNewRowBefore($table['total'],20);$table=locateBiayaInputTables($t,true)[4];for($i=1;$i<50;$i++){$r=$table['first']+$i;foreach(['B'=>'D','C'=>$i+1,'D'=>'Synthetic GB5 extra '.$i,'E'=>2] as $col=>$value)$t->setCellValue($col.$r,$value);if($i>=30){$t->setCellValue('A'.$r,null);$a->setCellValue('A'.$r,null);}}
 // Excel/Calc adjusts cross-sheet references on row insertion; mirror that in this synthetic fixture.
 foreach(locateBiayaInputTables($a,true) as $i=>$actual){$target=locateBiayaInputTables($t,true)[$i];for($r=$actual['first'];$r<=$actual['last'];$r++)foreach(['B','C','D'] as $col)$a->setCellValue($col.$r,"='".$targetName."'!".$col.($target['first']+$r-$actual['first']));}
 $t->insertNewRowBefore(1,2);$a->insertNewRowBefore(1,3);$t->insertNewColumnBefore('E');$a->insertNewColumnBefore('E');
 // Keep source references valid despite PhpSpreadsheet's quoted-sheet row-edit limitation.
 $targetTables=locateBiayaInputTables($t,true);foreach(locateBiayaInputTables($a,true) as $i=>$actual){$target=$targetTables[$i];for($r=$actual['first'];$r<=$actual['last'];$r++)foreach(['category','number','name'] as $key){$col=\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($target['identity'][$key]);$a->setCellValue([$actual['identity'][$key],$r],"='".$targetName."'!".$col.($target['first']+$r-$actual['first']));}}
 foreach($book->getAllSheets() as $sheet)foreach($sheet->getHyperlinkCollection() as $address=>$link)if($link->getUrl()==='')$sheet->setHyperlink($address,null);\PhpOffice\PhpSpreadsheet\Calculation\Calculation::getInstance($book)->clearCalculationCache();
 $rows=parseBiayaProducts($book,$year);$gb5=array_values(array_filter($rows,fn($r)=>$r['gb']===5&&$r['type']==='target'));groupBiayaCheck(count($gb5)===50&&$gb5[49]['number']===50,'Added rows belong to GB5 even when GB cell blank');groupBiayaCheck($gb5[0]['values'][0]===($year===2026?5000.0:5.0),'Legacy GB5 storage scale unchanged');groupBiayaCheck(count($rows)===110,'Only products, no subtotal double counting');
 foreach(['Xlsx','Ods'] as $format){$path=tempnam('/tmp','biaya-six-');try{$w=\PhpOffice\PhpSpreadsheet\IOFactory::createWriter($book,$format);$w->setPreCalculateFormulas(false);$w->save($path);$loaded=\PhpOffice\PhpSpreadsheet\IOFactory::load($path);groupBiayaCheck(parseBiayaProducts($loaded,$year)===$rows,'Six-table XLSX/ODS upload after inserted rows and shifted columns');$loaded->disconnectWorksheets();}finally{unlink($path);}}
 $records=[];foreach($rows as $row){$record=['report_year'=>$year,'report_period'=>$year.'-10','jenis'=>$row['type'],'gb'=>$row['gb'],'kategori'=>$row['category'],'nomor_produk'=>$row['number'],'nama_produk'=>$row['name']];foreach(['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'] as $m=>$key)$record[$key]=$row['values'][$m];$records[]=$record;}$next=buildBiayaTemplateWithHistory($year.'-11',$records);groupBiayaCheck(parseBiayaProducts($next,$year)===$rows,'Products and values restored into correct GB tables');groupBiayaCheck(locateBiayaInputTables($next->getSheetByName($targetName),true)[4]['last']-locateBiayaInputTables($next->getSheetByName($targetName),true)[4]['first']+1===50,'Next download grows GB5');$next->disconnectWorksheets();$book->disconnectWorksheets();
}
echo "PASS BIAYA two sheets x six GB tables, linked identities, simple subtotals, expanded/shifted rows and columns, inferred GB, no double count, signed/zero, units, XLSX/ODS and history for 2025/2026/2027\n";
